from pathlib import Path
root=Path('/opt/data/HeRmEz/projects')
ignore_dirs={'node_modules','.git','.vercel','.venv','venv','__pycache__','.expo','build','dist','legacy-src'}
projects=[]
for d in sorted([p for p in root.iterdir() if p.is_dir() and p.name not in {'_backups','cox-elementary-pta','legacy-src','deployment_docs'}], key=lambda p:p.name.lower()):
    def walk_match(name):
        out=[]
        for p in d.rglob(name):
            if any(part in ignore_dirs for part in p.parts): continue
            out.append(p)
        return out
    packages=walk_match('package.json')
    vercels=walk_match('vercel.json')
    reqs=walk_match('requirements.txt')
    manages=walk_match('manage.py')
    readmes=[p for p in d.glob('README*')]+[p for p in d.glob('PROJECT*')]
    package_info=[]
    for p in packages[:8]:
        try:
            j=json.loads(p.read_text(errors='ignore'))
            scripts=j.get('scripts',{})
            deps={**j.get('dependencies',{}), **j.get('devDependencies',{})}
            fw=[]
            for k in ['next','vite','react-scripts','@angular/cli','expo','react','vue','svelte']:
                if k in deps: fw.append(k)
            package_info.append({'path':str(p.relative_to(d)), 'scripts':list(scripts.keys()), 'fw':fw})
        except Exception as e:
            package_info.append({'path':str(p.relative_to(d)), 'error':str(e)})
    projects.append({'name':d.name,'packages':package_info,'vercel_json':[str(p.relative_to(d)) for p in vercels],'requirements':[str(p.relative_to(d)) for p in reqs[:5]],'manage_py':[str(p.relative_to(d)) for p in manages], 'readmes':[p.name for p in readmes[:3]]})
